    private void swipe(View target,float horizontal,float vertical)throws Exception{settle();int[] xy=new int[2];target.getLocationOnScreen(xy);float x=xy[0]+target.getWidth()*(horizontal<0?.80f:horizontal>0?.20f:.5f),y=xy[1]+target.getHeight()*(vertical<0?.78f:.65f);float dx=target.getWidth()*horizontal,dy=target.getHeight()*vertical;long now=SystemClock.uptimeMillis();motion(now,now,MotionEvent.ACTION_DOWN,x,y);for(int i=1;i<=12;i++)motion(now,now+i*16,MotionEvent.ACTION_MOVE,x+dx*i/12,y+dy*i/12);motion(now,now+208,MotionEvent.ACTION_UP,x+dx,y+dy);settle();if(target.getClass().getName().endsWith("SubcategorySwipeLayout")){JSONObject trace=new JSONObject().put("dx",horizontal).put("dy",vertical).put("width",target.getWidth()).put("height",target.getHeight()).put("screenX",xy[0]).put("screenY",xy[1]).put("attachedAfter",target.isAttachedToWindow()).put("trackingAfter",get(target,"tracking")).put("blocked",get(target,"blocked")).put("capturedAfter",get(target,"captured")).put("initial",get(target,"initial")).put("selectedAfter",((IntSupplier)get(target,"selected")).getAsInt()).put("enabledAfter",((BooleanSupplier)get(target,"enabled")).getAsBoolean());gestureTraces.put(trace);}}
